def build_itp_parts_bc_items(pack_num: int) -> list[dict]:
    """Builds 2 Part B (8 items) + 3 Part C (12 items) = 20 items (Q031..Q050) for pack 1..5."""
    items = []
    q_idx = 31
    for grp_id, grp_tag, turns, qs in _PART_BC[pack_num]:
        assert len(qs) == 4, f"Pack {pack_num} {grp_id} needs 4 questions"
        aid = f"ITP0{pack_num}-{grp_id}"
        for sub_i, (qtext, opts, cidx, mod, diff, exp) in enumerate(qs, start=1):
            qid = f"ITP-L1-0{pack_num}-Q{q_idx:03d}"
            prompt = f"Listen to {grp_tag} — Item {sub_i}/4. {qtext}"
            items.append(
                rotated_mcq(
                    qid=qid,
                    section="LISTENING",
                    prompt=prompt,
                    options=opts,
                    correct_idx=cidx,
                    explanation=exp,
                    rationale_source=mod,
                    difficulty=diff,
                    seed=pack_num * 11 + q_idx,
                    audio_id=aid,
                    audio_turns=turns if sub_i == 1 else [],
                ),
            )
            q_idx += 1
    assert len(items) == 20
    return items
